import os
import sys
import zipimport


if sys.version.startswith('2'):
    import new
else:
    import types


class core(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    """
    use remoteswinglibrary-2.3.0 to implement swing
    """

    def __init__(self, port=0, debug=False):
        """
        Init core, create RemoteSwingLibrary instance
        :param port: optional port for the server receiving connections from remote agents
        :param debug: optional flag that will start agent in mode with more logging for troubleshooting
                      (set to TRUE to enable)
        """
        _cur_dir = os.path.dirname(os.path.abspath(__file__))
        jar_path = os.path.join(_cur_dir, 'remoteswinglibrary-2.3.0.jar')
        importer = zipimport.zipimporter(jar_path)

        robotbackgroundlogger = importer.load_module("robotbackgroundlogger")
        swinglibrary = importer.load_module("swinglibrary")
        rsl = importer.load_module("RemoteSwingLibrary")

        self._javaws_path = None
        self._remote_swing = rsl.RemoteSwingLibrary(port, debug)
        self._add_swing_keyword(swinglibrary)

    def setup(self, javaws_path=None):
        """
        setup javaws path environment
        :param javaws_path: set javaws path, default will search javaws path in os
        """
        self._javaws_path = javaws_path if javaws_path else os.popen('which javaws').read().strip()
        if not self._javaws_path:
            raise Exception('javaws not found')

    def start_application(self, alias, jnlp_file, timeout=60, name_contains="", close_security_dialogs=False,
                          remote_port=0):
        """Starts the process in the `command` parameter  on the host operating system.
        The given alias is stored to identify the started application in RemoteSwingLibrary.
        :param jnlp_file: java app file path
        :param timeout: timeout in seconds (default 60).
        :param name_contains: a text that must be part of the name of the java process that we are connecting to.
                              name_contains helps in situations where multiple java-processes are started.
                              To see the name of the connecting java agents run tests with --loglevel DEBUG.
        :param close_security_dialogs: close security dialogs set flag
        :param remote_port: remote port
        """
        command = "{javaws_path} -verbose {jnlp_file}".format(javaws_path=self._javaws_path, jnlp_file=jnlp_file)
        self._remote_swing.start_application(alias, command, timeout, name_contains, close_security_dialogs,
                                             remote_port)

    def application_started(self, alias, timeout=60, name_contains="", remote_port=0, remote_host="127.0.0.1"):
        """Detects new RemoteSwingLibrary Java-agents in applications that are started without
        using the Start Application -keyword. The given alias is stored to identify the
        started application in RemoteSwingLibrary.
        Subsequent keywords will be passed on to this application.
        :param alias: java app alias name
        :param timeout: timeout in seconds (default 60).
        :param name_contains: a text that must be part of the name of the java process that we are connecting to.
                              name_contains helps in situations where multiple java-processes are started.
                              To see the name of the connecting java agents run tests with --loglevel DEBUG.
        :param remote_port: remote port
        :param remote_host: remote host ip
        """
        self._remote_swing.application_started(alias, timeout, name_contains, remote_port, remote_host)

    def switch_to_application(self, alias):
        """Switches between applications that are known to RemoteSwingLibrary.
        The application is identified using the alias.
        Subsequent keywords will be passed on to this application.
        :param alias: java app alias name
        """
        self._remote_swing.switch_to_application(alias)

    @staticmethod
    def _get_formatted_param(param_str):
        """get formatted param str. eg. 'time' -->'time', 'time=123'-->'time="123"'
        :param str param_str: key in keyword_arguments dict from swinglibrary.py
        :return: str, formatted param str
        """
        if "=" not in param_str:
            return param_str
        index = param_str.find('=')
        return param_str[:index + 1] + '"' + param_str[index + 1:] + '"'

    def _get_params_without_space(self, swing_keyword_name, arguments_kws):
        """get params list and params keys without space.
        eg. clickOnTableCell:
            return params_list: ['identifier', 'row', 'column', 'clickCountString="1"',
                                              'buttonString="BUTTON1_MASK"', '*keyModifierStrings']
                   param_keys: ['identifier', 'row', 'column', 'clickCountString', 'buttonString', '*keyModifierStrings']
        :param str swing_keyword_name: key in keyword_arguments dict from swinglibrary.py
        :param arguments_kws: keyword_arguments dict from swinglibrary.py
        """
        params_list = []
        params_keys = []

        for item in arguments_kws[swing_keyword_name]:
            if " " not in item.split("=")[0]:
                params_list.append(self._get_formatted_param(item))
                params_keys.append(item.split("=")[0])

        return params_list, params_keys

    @staticmethod
    def _get_func_str_with_params(swing_keyword_name, params_keys, params_list):
        params_str = ','.join(params_list)
        arg_name_with_star = ''

        if params_keys[-1:][0].startswith("*"):
            arg_name_with_star = params_keys[-1:][0][1:]
            params_list_str = '[' + ','.join(params_keys[:-1]) + ']'
        else:
            params_list_str = '[' + ','.join(params_keys) + ']'

        return ("def {func_name}(self, {params}):\n"
                "    args=tuple({params_list_str} + list({arg_name_with_star}))\n"
                "    kwargs=dict()\n"
                "    return self._remote_swing.run_keyword('{func_name}', args, kwargs)"
                .format(func_name=swing_keyword_name,
                        params=params_str,
                        params_list_str=params_list_str,
                        arg_name_with_star=arg_name_with_star))

    @staticmethod
    def _get_func_str_without_params(swing_keyword_name):
        return ("def {func_name}(self):\n"
                "    return self._remote_swing.run_keyword('{func_name}', (), dict())"
                .format(func_name=swing_keyword_name))

    @staticmethod
    def _get_set_jemmy_dispatch_model_func_str():
        return ("def setJemmyDispatchModel(self, *args, **kwargs):\n"
                "    if kwargs.get('dispatch model', None):\n"
                "        args=(kwargs['dispatch model'],)\n"
                "        kwargs=dict()\n"
                "    return self._remote_swing.run_keyword('setJemmyDispatchModel', args, kwargs)")

    def _get_func_str(self, swing_keyword_name, arguments_kws):
        params_list, params_keys = self._get_params_without_space(swing_keyword_name, arguments_kws)

        if swing_keyword_name == "setJemmyDispatchModel":
            func_str = self._get_set_jemmy_dispatch_model_func_str()
        elif len(params_keys) > 0:
            func_str = self._get_func_str_with_params(swing_keyword_name, params_keys, params_list)
        else:
            func_str = self._get_func_str_without_params(swing_keyword_name)
        return func_str

    def _add_swing_keyword(self, swinglibrary):
        arguments_kws = swinglibrary.keyword_arguments
        for swing_keyword_name in swinglibrary.keywords:
            func_definition_str = self._get_func_str(swing_keyword_name, arguments_kws)
            exec(func_definition_str)

            if swing_keyword_name != 'startApplication':
                if sys.version.startswith('2'):
                    exec('self.{func_name} =  new.instancemethod({func_name}, self, core)'.format(func_name=swing_keyword_name))
                else:
                    exec('self.{func_name} =  types.MethodType({func_name}, self)'.format(func_name=swing_keyword_name))

    def teardown(self):
        """ Uses the RemoteSwingLibrary java agent to call system exit for the current java application.
        """
        self._remote_swing.system_exit()
